def comps(mask):
    from collections import deque
    H,W=mask.shape; seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if mask[i,j] and (i,j) not in seen:
                q=deque([(i,j)]); comp=set(); seen.add((i,j))
                while q:
